// Shared comment threads, compact reaction chips and local attachment drafts.
const fileDrafts={},threadExpanded=new Set();let commentReactionOpen=null,commentEmojiSearch='';const replyDrafts={};
function draftKey(field){return field==='post-text'?'post':field==='reply-text'?'reply:'+replyParent:activePost}
function draftFiles(field){return fileDrafts[draftKey(field)]||[]}
function filesMarkup(files){return (files||[]).map(f=>`<div class="local-file">${f.kind==='image'?`<img src="${escapeHtml(f.url)}" alt="${escapeHtml(f.name)}">`:f.kind==='video'?`<video controls preload="metadata" src="${escapeHtml(f.url)}"></video>`:f.kind==='audio'?`<audio controls preload="metadata" src="${escapeHtml(f.url)}"></audio>`:''}<a href="${escapeHtml(f.url)}" download="${escapeHtml(f.name)}">${icon('image')}${escapeHtml(f.name)}</a></div>`).join('')}
function draftFilesMarkup(field){return draftFiles(field).map((f,i)=>`<div class="draft-file"><span>${escapeHtml(f.name)}</span><button type="button" data-remove-file="${i}" data-file-field="${field}" aria-label="Remove ${escapeHtml(f.name)}">${icon('close')}</button></div>`).join('')}
writingBox=function(id,value,kind){return `<div class="writing-row"><div class="writing-box ${kind}"><div class="attach-menu"><button type="button" data-attach-trigger="attach-${id}" aria-label="Add attachment">${icon('plus')}</button><div id="attach-${id}" class="attach-options" popover="auto"><label>${icon('image')}Photos or media<input type="file" class="visually-hidden" data-attachment-input="${id}" accept="image/jpeg,image/png,image/webp,image/avif,video/*,audio/*" multiple></label><label>${icon('plus')}Choose files<input type="file" class="visually-hidden" data-attachment-input="${id}" multiple></label></div></div><textarea id="${id}" rows="${kind==='comment-writing'?1:5}" maxlength="${kind==='comment-writing'?1500:3000}" placeholder="${kind==='comment-writing'?'Add a comment…':'What’s on your mind?'}">${escapeHtml(value)}</textarea><button type="submit" class="send-button" aria-label="${kind==='comment-writing'?'Send comment':'Post'}">${icon('send')}</button></div></div><div data-file-drafts="${id}">${draftFilesMarkup(id)}</div>`};
function commentReactions(c){const rs=c.reactions||[];return `<div class="comment-actions">${timeMarkup(c.createdAt||startedAt)}<button class="text-button" data-comment-react="${c.id}" aria-label="React to comment">${icon('heart')}React</button><button class="text-button" data-reply-id="${c.id}">Reply</button><span class="small-reaction-chips">${rs.map(e=>`<button data-comment-emoji="${escapeHtml(e)}" data-comment-id="${c.id}" aria-pressed="true">${escapeHtml(e)} <span>1</span></button>`).join('')}</span></div>${commentReactionOpen===c.id?`<div class="comment-emoji-picker"><div class="quick-emoji">${['❤️','👏','😂','🎉','🙏'].map(e=>`<button data-comment-emoji="${e}" data-comment-id="${c.id}">${e}</button>`).join('')}</div><label class="sr-only" for="comment-emoji-search">Find emoji</label><input id="comment-emoji-search" type="search" placeholder="Find any emoji…" value="${escapeHtml(commentEmojiSearch)}"><div id="comment-emoji-results">${commentEmojiResults(c.id)}</div></div>`:''}`}
function commentEmojiResults(id){return `<div class="emoji-grid">${emojiChoices().filter(e=>!commentEmojiSearch||e.search.includes(commentEmojiSearch)||e.native.includes(commentEmojiSearch)).slice(0,100).map(e=>`<button data-comment-emoji="${escapeHtml(e.native)}" data-comment-id="${id}" aria-label="${escapeHtml(e.name)}">${escapeHtml(e.native)}</button>`).join('')}</div>`}
commentTree=function(id,parent=null,depth=0){const all=preview.comments[id]||[];return all.filter(c=>c.parent===parent).map(c=>{const p=commentMember(c),children=all.filter(x=>x.parent===c.id);return `<article class="thread-comment depth-${Math.min(depth,3)}"><div class="comment-row"><button class="comment-avatar" data-member-card="${escapeHtml(p.id)}" aria-label="View ${escapeHtml(p.name)}'s profile card">${avatarMarkup(p.photo,p.name)}</button><div class="comment-content"><div class="chat-bubble"><button class="comment-name" data-member-card="${escapeHtml(p.id)}">${escapeHtml(p.name)}</button>${depth?'<span class="reply-label">Reply</span>':''}${c.text?`<p>${escapeHtml(c.text)}</p>`:''}${filesMarkup(c.files)}</div>${commentReactions(c)}</div></div>${replyParent===c.id?`<div class="inline-reply">${commentComposer(id,c.id)}</div>`:''}${children.length?`<details class="thread-replies" data-thread="${c.id}" ${threadExpanded.has(c.id)?'open':''}><summary>${children.length} ${children.length===1?'reply':'replies'}</summary>${commentTree(id,c.id,depth+1)}</details>`:''}</article>`}).join('')};
function commentComposer(id,parent){const target=(preview.comments[id]||[]).find(c=>c.id===parent);const inline=!!target;return `<form id="${inline?'reply-form':'comment-form'}" class="conversation-composer ${inline?'inline-composer':''}">${inline?`<div class="replying-to">Replying to ${escapeHtml(target.name)}<button type="button" class="text-button" data-preview-action="cancel-reply">Cancel</button></div>`:''}${writingBox(inline?'reply-text':'comment-text',inline?(replyDrafts[parent]||''):(commentDrafts[id]||''),'comment-writing')}<p id="${inline?'reply-error':'comment-error'}" class="form-error" role="alert"></p></form>`}
showComments=function(id,parent=null,focus=false){if(!knownPost(id))return;captureCommentDraft();activePost=id;replyParent=parent;modal('Comments',`<div class="comments-list chat-thread">${commentTree(id)||'<p class="muted empty-conversation">Be the first to say something.</p>'}</div>${commentComposer(id,null)}`);$('#sheet').classList.add('comments-surface');$('#sheet').dataset.postId=id;if(parent){threadExpanded.add(parent);$('#reply-text')?.focus?.()}else if(focus)$('#comment-text')?.focus?.()};
function showFullPost(id){if(!knownPost(id))return;captureCommentDraft();activePost=id;replyParent=null;modal('Family post',`<article class="focused-post">${postDetail(id)}${postActions(id,false,true)}</article><div class="comments-list chat-thread">${commentTree(id)}</div>${commentComposer(id,null)}`);$('#sheet').classList.add('focus-surface');$('#sheet').dataset.postId=id;$('#sheet').dataset.fullPost='true'}
const modalBeforeThreads=modal;modal=function(title,html){$('#sheet').classList.remove('comments-surface');delete $('#sheet').dataset.fullPost;modalBeforeThreads(title,html)};
function refreshCommentView(){const id=$('#sheet').dataset.postId||activePost;captureCommentDraft();if($('#sheet').dataset.fullPost)showFullPost(id);else showComments(id,replyParent)}
function toggleCommentReaction(id,emoji){const c=(preview.comments[activePost]||[]).find(x=>x.id===id);if(!c||!emojiChoices().some(x=>x.native===emoji))return false;const r=c.reactions||(c.reactions=[]),i=r.indexOf(emoji);if(i<0)r.push(emoji);else r.splice(i,1);return true}
const saveBeforeThreads=savePreviewForm;
savePreviewForm=function(id){
 if(id!=='comment-form'&&id!=='reply-form')return saveBeforeThreads(id);
 const inline=id==='reply-form',field=inline?'reply-text':'comment-text',input=$('#'+field);
 const text=input.value.trim(),files=draftFiles(field),error=$('#'+(inline?'reply-error':'comment-error'));
 if(text.length>1500||(!text&&!files.length)){error.textContent='Write a comment or add an attachment.';return false}
 const parent=inline?replyParent:null;let cursor=parent,depth=0;
 const all=preview.comments[activePost]||[];
 while(cursor){const c=all.find(x=>x.id===cursor);if(!c||++depth>3){error.textContent='Reply to an earlier comment in this thread.';return false}threadExpanded.add(cursor);cursor=c.parent}
 (preview.comments[activePost]||(preview.comments[activePost]=[])).push({id:'c'+(++previewId),parent,text,name:preview.profile.name,memberId:'self',createdAt:Date.now(),files:[...files],reactions:[]});
 fileDrafts[draftKey(field)]=[];
 if(inline)replyDrafts[parent]='';else commentDrafts[activePost]='';
 input.value='';replyParent=null;render();refreshCommentView();return true
};
const mediaBeforeThreads=postMedia;postMedia=function(p){return mediaBeforeThreads(p)+filesMarkup(p.files)};
const publishBeforeThreads=publishPreviewPost;publishPreviewPost=function(){const files=[...draftFiles('post-text')];composer.files=files;const ok=publishBeforeThreads();if(ok){preview.posts[0].files=files;fileDrafts.post=[];render()}return ok};
function loadLocalFiles(field,files){const key=draftKey(field),list=fileDrafts[key]||(fileDrafts[key]=[]);for(const f of Array.from(files)){if(list.length>=4){toast('Up to 4 attachments at a time.');break}if(f.size>20*1024*1024){toast('Choose files smaller than 20 MB.');continue}const kind=/^image\/(jpeg|png|webp|avif)$/.test(f.type)?'image':f.type.startsWith('video/')?'video':f.type.startsWith('audio/')?'audio':'file';const blob=kind==='file'?new Blob([f],{type:'application/octet-stream'}):f;list.push({name:f.name.slice(0,160),kind,url:URL.createObjectURL(blob),size:f.size})}const box=document.querySelector(`[data-file-drafts="${field}"]`);if(box)box.innerHTML=draftFilesMarkup(field)}
document.addEventListener('change',e=>{if(e.target.dataset.attachmentInput){loadLocalFiles(e.target.dataset.attachmentInput,e.target.files);e.target.value='';e.target.closest('details')?.removeAttribute('open')}});
document.addEventListener('input',e=>{if(e.target.id==='reply-text'&&replyParent)replyDrafts[replyParent]=e.target.value;if(e.target.id==='comment-emoji-search'){commentEmojiSearch=e.target.value.toLowerCase();$('#comment-emoji-results').innerHTML=commentEmojiResults(commentReactionOpen)}});
document.addEventListener('toggle',e=>{if(e.target.dataset?.thread){if(e.target.open)threadExpanded.add(e.target.dataset.thread);else threadExpanded.delete(e.target.dataset.thread)}},true);
document.addEventListener('click',e=>{const reaction=e.target.closest('[data-comment-react]');if(reaction){e.preventDefault();e.stopImmediatePropagation();commentReactionOpen=commentReactionOpen===reaction.dataset.commentReact?null:reaction.dataset.commentReact;commentEmojiSearch='';refreshCommentView();return}const emoji=e.target.closest('[data-comment-emoji]');if(emoji){e.preventDefault();e.stopImmediatePropagation();toggleCommentReaction(emoji.dataset.commentId,emoji.dataset.commentEmoji);commentReactionOpen=null;refreshCommentView();return}const remove=e.target.closest('[data-remove-file]');if(remove){e.preventDefault();const field=remove.dataset.fileField,list=draftFiles(field),removed=list.splice(Number(remove.dataset.removeFile),1)[0];if(removed)URL.revokeObjectURL(removed.url);document.querySelector(`[data-file-drafts="${field}"]`).innerHTML=draftFilesMarkup(field);return}const full=e.target.closest('[data-open-post]');if(full){e.preventDefault();e.stopImmediatePropagation();showFullPost(full.dataset.openPost)}},true);
function linkedPostHeader(id){const p=preview.posts.find(x=>x.id===id),person=p?{id:'self',...preview.profile}:{id:'planning-crew',name:'The planning crew',photo:null,bio:'Green & White reunion planning',socials:[]};commentMembers.set(person.id,person);const when=p?.createdAt||startedAt-86400000;return `<div class="row post-head"><button class="comment-avatar" data-member-card="${person.id}" aria-label="View ${escapeHtml(person.name)}'s profile card">${avatarMarkup(person.photo,person.name)}</button><div><button class="comment-name" data-member-card="${person.id}">${escapeHtml(person.name)}</button>${timeMarkup(when).replace('data-exact-time=',`data-open-post="${id}" data-exact-time=`)}</div></div>`}
const homeBeforeThreads=home;home=function(){let i=0;const ids=[...preview.posts.map(p=>p.id),'photo','poll'];return homeBeforeThreads().replace(/<div class="row post-head">[\s\S]*?<\/div><\/div>/g,()=>linkedPostHeader(ids[i++]||'photo'))};
const detailBeforeThreads=postDetail;postDetail=function(id){return detailBeforeThreads(id).replace(/<div class="row post-head">[\s\S]*?<\/div><\/div>/,linkedPostHeader(id))};
const postActionsBeforeThreads=postActions;postActions=function(...args){const id=args[0],reactions=preview.reactions[id]||[];let html=postActionsBeforeThreads(...args);if(reactions.length)html=html.replace(/<span class="reaction-faces">[\s\S]*?<\/span><span>\d+<\/span>/,`<span class="small-reaction-chips">${reactions.map(e=>`<span class="reaction-pill">${escapeHtml(e)} <small>1</small></span>`).join('')}</span>`);return html};
render();
